namespace hanmo::resident {
Outcome<EconomicTakeoverExecutionState> decode_economic_takeover_execution(const BoundaryValue& value){auto valid=validate_economic_payload_fields(value);if(!valid.ok)return {false,{},valid.error};try{auto result=dynamic_economy_codec::decode_root<EconomicTakeoverExecutionState>(value,"/economic_takeover_execution");if(result.version!=1)boundary::unsupported("EconomicTakeoverExecutionVersionMismatch","/economic_takeover_execution/version");return {true,std::move(result),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_economic_takeover_execution_fields(ProjectionWriter& writer,const EconomicTakeoverExecutionState& state){try{if(state.version!=1)boundary::unsupported("EconomicTakeoverExecutionVersionMismatch","/economic_takeover_execution/version");return dynamic_economy_codec::emit_fields(writer,state);}catch(const boundary::DecodeFailure&failure){return writer.reject(failure.error.original.code,failure.error.original.path);}}
BoundaryValue encode_economic_takeover_execution(const EconomicTakeoverExecutionState& state){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto&fields){return emit_economic_takeover_execution_fields(fields,state);});if(valid.ok)valid=writer.finish();if(!valid.ok)throw boundary::DecodeFailure{valid.error};return out;}
Status visit_economic_takeover_execution_checkpoint(CodecVisitor& visitor,EconomicTakeoverExecutionState& state){if(!visitor.reading()&&state.version!=1)return visitor.reject("EconomicTakeoverExecutionVersionMismatch");auto result=dynamic_economy_codec::checkpoint(visitor,"economic_takeover_execution",state,false,false,false,false);if(!result.ok)return result;if(state.version!=1)return visitor.reject("EconomicTakeoverExecutionVersionMismatch");return result;}
}
